={{ (() => {
  const data = $json;
  const messages = [];
  if (data.system) {
    messages.push({ role: 'system', content: data.system });
  }
  messages.push(...data.messages);
  const corps = { model: data.model, messages: messages };
  // Les modèles de raisonnement (gpt-5*, o1*, o3*, o4*) refusent les deux
  // paramètres historiques, avec un 400 : « Unsupported parameter: 'max_tokens'
  // is not supported with this model. Use 'max_completion_tokens' instead. » et
  // « Unsupported value: 'temperature' does not support 0.7 ». C'est ce 400 que
  // le webhook rendait en 500 (azy.daily#276).
  if (data.raisonnement) {
    // Le budget est partagé avec les jetons de raisonnement, invisibles dans la
    // réponse : à 16 jetons, gpt-5 en consomme 16 à réfléchir et rend un texte
    // VIDE, en HTTP 200. Un plancher évite ce succès creux.
    corps.max_completion_tokens = Math.max(data.max_tokens, 1024);
  } else {
    corps.max_tokens = data.max_tokens;
    corps.temperature = data.temperature;
  }
  return JSON.stringify(corps);
})() }}

