// ============================================
// FORMAT ANTHROPIC RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;

// Handle error response
if (input.error) {
    // Le statut réel n'était pas remonté : un 400 « payload invalide » ressortait
  // en 500, et l'appelant cherchait une panne serveur. Avec
  // onError=continueRegularOutput, statusCode est absent et le statut est enfoui
  // dans le message sous la forme « 400 - {...} » (azy.daily#276, #442).
  let statut = input.statusCode;
  if (statut === undefined) {
    const brut = String(input.error?.message || input.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    statut = m ? parseInt(m[1], 10) : 502;
  }
  return {
    success: false,
    error: {
      code: input.error.type || 'ANTHROPIC_ERROR',
      message: input.error.message || 'Anthropic API error',
      http_status: statut
    },
    metadata: prevData.metadata,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'anthropic',
      model: prevData.model,
      tokens: { input: 0, output: 0 },
      latency_ms: latencyMs
    }
  };
}

// Sources : { title, url, domain }, dedoublonnees par URL — la forme de
// l outil web-search, pour que les clients n aient qu un parseur (azy.daily#361).
const domaineDe = (url) => { const m = String(url || '').match(/^https?:\/\/([^\/]+)/); return m ? m[1] : ''; };
const sources = [];
const vues = new Set();
const ajouter = (titre, url, domaine) => {
  if (!url || vues.has(url)) return;
  vues.add(url);
  sources.push({ title: titre || 'Source', url: url, domain: domaine || domaineDe(url) });
};

// ⚠️ Avec la recherche web, content[0] est l appel d outil (server_tool_use),
// pas le texte : lire content[0].text rendait une reponse VIDE. Le texte est
// reparti en plusieurs blocs, un par passage cite. Mesure du 2026-09-10.
const blocs = Array.isArray(input.content) ? input.content : [];
const text = blocs.filter(b => b.type === 'text').map(b => b.text || '').join('');

// Les sources CITEES dans le texte d abord ; a defaut, les resultats recuperes.
for (const b of blocs) {
  if (b.type !== 'text') continue;
  for (const c of (b.citations || [])) {
    if (c.type === 'web_search_result_location') ajouter(c.title, c.url);
  }
}
if (!sources.length) {
  for (const b of blocs) {
    if (b.type === 'web_search_tool_result' && Array.isArray(b.content)) {
      for (const r of b.content) if (r.type === 'web_search_result') ajouter(r.title, r.url);
    }
  }
}
const recherches = input.usage?.server_tool_use?.web_search_requests
  || blocs.filter(b => b.type === 'server_tool_use' && b.name === 'web_search').length;

// En mode recherche, un 200 sans texte est un echec : pause_turn ou budget epuise.
if (prevData.web_search && !text) {
  return {
    success: false,
    error: { code: 'EMPTY_RESPONSE', message: 'Anthropic a repondu sans texte (stop_reason ' + (input.stop_reason || '?') + ')', http_status: 502 },
    metadata: prevData.metadata,
    _trace: { llm_response: null, service_response: input, provider: 'anthropic', model: prevData.model, tokens: { input: 0, output: 0 }, latency_ms: latencyMs }
  };
}
const stopReason = input.stop_reason || 'end_turn';
const modelUsed = input.model || prevData.model;

const res = {
  success: true,
  data: {
    text: text,
    model: modelUsed,
    finish_reason: stopReason
  },
  meta: {
    provider: 'anthropic',
    model: modelUsed,
    usage: {
      // Le triplet historique est CONSERVÉ : chat.api bascule à son rythme.
      prompt_tokens: input.usage?.input_tokens || 0,
      completion_tokens: input.usage?.output_tokens || 0,
      total_tokens: (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0),
      // Ajoutés : les jetons de cache ne sont pas facturés au plein tarif —
      // 0,1× en lecture, 1,25× en écriture. Les jeter faisait surfacturer la
      // lecture et ignorer l'écriture (azy.daily#287, §2.4).
      // Toujours présents, à 0 quand le fournisseur ne les rend pas : un champ
      // absent et un champ nul ne se distinguent pas en aval.
      cache_read_input_tokens: input.usage?.cache_read_input_tokens || 0,
      cache_creation_input_tokens: input.usage?.cache_creation_input_tokens || 0,
      reasoning_tokens: 0
    }
  },
  metadata: prevData.metadata,
  _trace: {
    llm_response: text,
    service_response: input,
    provider: 'anthropic',
    model: modelUsed,
    tokens: {
      input: input.usage?.input_tokens || 0,
      output: input.usage?.output_tokens || 0
    },
    latency_ms: latencyMs
  }
};
if (prevData.web_search) {
  res.data.sources = sources;
  res.meta.search_performed = recherches > 0 || sources.length > 0;
  res.meta.sources_count = sources.length;
  res.meta.usage.web_search_requests = recherches;
}
return res;

// ============================================
// FORMAT OPENAI RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;

// Handle error response
if (input.error) {
  // Le statut réel n'était pas remonté : un 400 « paramètre non supporté »
  // ressortait en 500, et l'appelant cherchait une panne serveur pour une
  // requête malformée (azy.daily#276, même famille que n8n-workflows#442).
  // Avec onError=continueRegularOutput, statusCode est absent et le statut est
  // enfoui dans le message sous la forme « 400 - {...} ».
  let statut = input.statusCode;
  if (statut === undefined) {
    const brut = String(input.error.message || input.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    statut = m ? parseInt(m[1], 10) : 502;
  }
  return {
    success: false,
    error: {
      code: input.error.code || 'OPENAI_ERROR',
      message: input.error.message || 'OpenAI API error',
      http_status: statut
    },
    metadata: prevData.metadata,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'openai',
      model: prevData.model,
      tokens: { input: 0, output: 0 },
      latency_ms: latencyMs
    }
  };
}

const text = input.choices?.[0]?.message?.content || '';
const finishReason = input.choices?.[0]?.finish_reason || 'stop';
const modelUsed = input.model || prevData.model;

return {
  success: true,
  data: {
    text: text,
    model: modelUsed,
    finish_reason: finishReason
  },
  meta: {
    provider: 'openai',
    model: modelUsed,
    usage: {
      prompt_tokens: input.usage?.prompt_tokens || 0,
      completion_tokens: input.usage?.completion_tokens || 0,
      total_tokens: input.usage?.total_tokens || 0,
      // OpenAI place le cache dans `prompt_tokens_details.cached_tokens`, et les
      // jetons de raisonnement sont DÉJÀ compris dans completion_tokens — le
      // détail est fourni en supplément, jamais en remplacement (azy.daily#287).
      cache_read_input_tokens: input.usage?.prompt_tokens_details?.cached_tokens || 0,
      cache_creation_input_tokens: 0,
      reasoning_tokens: input.usage?.completion_tokens_details?.reasoning_tokens || 0
    }
  },
  metadata: prevData.metadata,
  _trace: {
    llm_response: text,
    service_response: input,
    provider: 'openai',
    model: modelUsed,
    tokens: {
      input: input.usage?.prompt_tokens || 0,
      output: input.usage?.completion_tokens || 0
    },
    latency_ms: latencyMs
  }
};

// ============================================
// FORMAT MISTRAL RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;

// Handle error response
if (input.error || input.message) {
    // Le statut réel n'était pas remonté : un 400 « payload invalide » ressortait
  // en 500, et l'appelant cherchait une panne serveur. Avec
  // onError=continueRegularOutput, statusCode est absent et le statut est enfoui
  // dans le message sous la forme « 400 - {...} » (azy.daily#276, #442).
  let statut = input.statusCode;
  if (statut === undefined) {
    const brut = String(input.error?.message || input.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    statut = m ? parseInt(m[1], 10) : 502;
  }
  return {
    success: false,
    error: {
      code: 'MISTRAL_ERROR',
      message: input.message || input.error?.message || 'Mistral API error',
      http_status: statut
    },
    metadata: prevData.metadata,
    _trace: {
      llm_response: null,
      service_response: input,
      provider: 'mistral',
      model: prevData.model,
      tokens: { input: 0, output: 0 },
      latency_ms: latencyMs
    }
  };
}

const text = input.choices?.[0]?.message?.content || '';
const finishReason = input.choices?.[0]?.finish_reason || 'stop';
const modelUsed = input.model || prevData.model;

return {
  success: true,
  data: {
    text: text,
    model: modelUsed,
    finish_reason: finishReason
  },
  meta: {
    provider: 'mistral',
    model: modelUsed,
    usage: {
      prompt_tokens: input.usage?.prompt_tokens || 0,
      completion_tokens: input.usage?.completion_tokens || 0,
      total_tokens: input.usage?.total_tokens || 0,
      // Mistral suit la forme d'OpenAI pour le cache (azy.daily#287).
      cache_read_input_tokens: input.usage?.prompt_tokens_details?.cached_tokens || 0,
      cache_creation_input_tokens: 0,
      reasoning_tokens: 0
    }
  },
  metadata: prevData.metadata,
  _trace: {
    llm_response: text,
    service_response: input,
    provider: 'mistral',
    model: modelUsed,
    tokens: {
      input: input.usage?.prompt_tokens || 0,
      output: input.usage?.completion_tokens || 0
    },
    latency_ms: latencyMs
  }
};

parameters.jsonBody:
={{ (() => {
  const data = $json;

  // Gemini n'a PAS le schéma d'OpenAI. Le relais brut « contents: data.messages »
  // produisait : 400 INVALID_ARGUMENT — Unknown name "content" at 'contents[0]'.
  //   OpenAI   role + content[] : blocs « type/text » et « type/image_url »
  //   Gemini   role + parts[]   : blocs « text » et « inline_data »
  //
  // ⚠️ Ne JAMAIS accoler deux accolades fermantes dans cette expression, même en
  // commentaire : n8n y lit la fin de l'expression et tronque tout le reste. Le
  // nœud rend alors « invalid syntax » sans qu'aucun appel ne soit parti — c'est
  // exactement ce qu'un commentaire illustrant la forme Gemini a provoqué ici.
  // et « assistant » s'y dit « model ».
  const morceau = (bloc) => {
    if (typeof bloc === 'string') return { text: bloc };
    // Bloc déjà natif Gemini : chat.api construit l'image au format du provider.
    if (bloc.inline_data || bloc.inlineData) return bloc;
    if (bloc.type === 'text' || typeof bloc.text === 'string') return { text: bloc.text || '' };
    // Repli défensif : un appelant qui enverrait l'image à la forme OpenAI.
    if (bloc.type === 'image_url' && bloc.image_url && bloc.image_url.url) {
      const m = String(bloc.image_url.url).match(/^data:([^;]+);base64,(.*)$/);
      if (m) return { inline_data: { mime_type: m[1], data: m[2] } };
    }
    return { text: '' };
  };

  const contents = (data.messages || []).map((m) => ({
    role: m.role === 'assistant' ? 'model' : 'user',
    parts: Array.isArray(m.content) ? m.content.map(morceau) : [morceau(m.content)],
  }));

  const b = {
    contents: contents,
    generationConfig: { maxOutputTokens: data.max_tokens, temperature: data.temperature },
  };
  if (data.system) b.systemInstruction = { parts: [{ text: data.system }] };
  // Recherche web (azy.daily#361) : ancrage Google Search.
  if (data.web_search) b.tools = [{ google_search: {} }];
  return JSON.stringify(b);
})() }}

