// ============================================
// FORMAT GEMINI (google) RESPONSE
// ============================================
const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;

if (input.error) {
    // Le statut réel n'était pas remonté : un 400 « payload invalide » ressortait
  // en 500, et l'appelant cherchait une panne serveur. Avec
  // onError=continueRegularOutput, statusCode est absent et le statut est enfoui
  // dans le message sous la forme « 400 - {...} » (azy.daily#276, #442).
  let statut = input.statusCode;
  if (statut === undefined) {
    const brut = String(input.error?.message || input.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    statut = m ? parseInt(m[1], 10) : 502;
  }
  return {
    success: false,
    error: {
      code: input.error.status || input.error.code || 'GEMINI_ERROR',
      message: input.error.message || 'Gemini API error',
      http_status: statut
    },
    metadata: prevData.metadata,
    _trace: { llm_response: null, service_response: input, provider: 'google',
      model: prevData.model, tokens: { input: 0, output: 0 }, latency_ms: latencyMs }
  };
}

const parts = (input.candidates && input.candidates[0] && input.candidates[0].content && input.candidates[0].content.parts) || [];
const text = parts.map(p => p.text || '').join('');
const finishReason = (input.candidates && input.candidates[0] && input.candidates[0].finishReason) || 'STOP';
const usage = input.usageMetadata || {};
const modelUsed = prevData.model;

// Sources : { title, url, domain }, dedoublonnees par URL — la forme de
// l outil web-search, pour que les clients n aient qu un parseur (azy.daily#361).
const domaineDe = (url) => { const m = String(url || '').match(/^https?:\/\/([^\/]+)/); return m ? m[1] : ''; };
const sources = [];
const vues = new Set();
const ajouter = (titre, url, domaine) => {
  if (!url || vues.has(url)) return;
  vues.add(url);
  sources.push({ title: titre || 'Source', url: url, domain: domaine || domaineDe(url) });
};

// ⚠️ L URL d ancrage est une REDIRECTION vertexaisearch.cloud.google.com ; le
// domaine reel n est que dans `title` (« wikipedia.org »). Mesure du 2026-09-10.
const ancrage = (input.candidates && input.candidates[0] && input.candidates[0].groundingMetadata) || {};
for (const ch of (ancrage.groundingChunks || [])) {
  if (!ch.web) continue;
  const d = domaineDe(ch.web.uri);
  ajouter(ch.web.title, ch.web.uri, /vertexaisearch/.test(d) ? (ch.web.title || d) : d);
}
const recherches = (ancrage.webSearchQueries || []).length;

if (prevData.web_search && !text) {
  return {
    success: false,
    error: { code: 'EMPTY_RESPONSE', message: 'Gemini a repondu sans texte (finishReason ' + finishReason + ')', http_status: 502 },
    metadata: prevData.metadata,
    _trace: { llm_response: null, service_response: input, provider: 'google', model: prevData.model, tokens: { input: 0, output: 0 }, latency_ms: latencyMs }
  };
}

const res = {
  success: true,
  data: { text: text, model: modelUsed, finish_reason: finishReason },
  meta: { provider: 'google', model: modelUsed,
    usage: {
      prompt_tokens: usage.promptTokenCount || 0,
      // ⚠️ Convention arrêtée avec l'API (azy.daily#295 §2.5) :
      //     output_tokens = candidatesTokenCount + thoughtsTokenCount
      // Sans elle, prompt + completion ≠ total — mesuré 2 + 7 contre un total
      // de 188, l'écart étant les 179 jetons de « pensée ». Google les facture,
      // et les exclure sous-comptait jusqu'à 95 % de la sortie.
      // Cette convention aligne aussi Gemini sur OpenAI, où les jetons de
      // raisonnement sont déjà compris dans completion_tokens.
      completion_tokens: (usage.candidatesTokenCount || 0) + (usage.thoughtsTokenCount || 0),
      total_tokens: usage.totalTokenCount || 0,
      cache_read_input_tokens: usage.cachedContentTokenCount || 0,
      cache_creation_input_tokens: 0,
      // Le détail vient EN SUPPLÉMENT du total, jamais à sa place.
      reasoning_tokens: usage.thoughtsTokenCount || 0
    } },
  metadata: prevData.metadata,
  _trace: { llm_response: text, service_response: input, provider: 'google',
    model: modelUsed,
    tokens: { input: usage.promptTokenCount || 0, output: usage.candidatesTokenCount || 0 },
    latency_ms: latencyMs }
};
if (prevData.web_search) {
  res.data.sources = sources;
  res.meta.search_performed = recherches > 0 || sources.length > 0;
  res.meta.sources_count = sources.length;
  res.meta.usage.web_search_requests = recherches;
}
return res;

// Ollama Cloud sert la surface compatible OpenAI ; la reponse a donc la meme
// forme. Mais l ETIQUETTE reste `ollama-cloud` de bout en bout : `openai`
// ferait compter l audit au prix d OpenAI (azy.daily#340).
// ============================================
// FORMAT OPENAI RESPONSE
// ============================================

// ⚠️ `Ollama Cloud API` porte fullResponse + neverError : il emet
// { statusCode, body, headers }, et JAMAIS l objet d erreur axios que
// Format OpenAI attend au premier niveau. Sans cette normalisation,
// `if (input.error)` est faux sur un 401 et la reponse ressort en SUCCES.
// Mesure du 2026-09-08 : une cle volontairement fausse rendait success:true.
const enveloppe = $input.first().json;
const input = enveloppe.body !== undefined ? enveloppe.body : enveloppe;

// Le statut vient de statusCode quand il existe (fullResponse), sinon du
// message d erreur — panne de transport, ou noeud sans fullResponse.
let statutHttp = enveloppe.statusCode;
if (statutHttp === undefined) {
  const msg = String((enveloppe.error && enveloppe.error.message) || enveloppe.message || '');
  const m = msg.match(/(\d{3})\s*-\s*/);
  statutHttp = m ? parseInt(m[1], 10) : ((enveloppe.error || enveloppe.code) ? 502 : 200);
}

const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;

// Handle error response
// Un statut >= 400 suffit : le corps d une erreur Ollama porte bien
// `error`, mais on ne s en remet pas a sa presence pour decider.
if (statutHttp >= 400 || input.error) {
  const statut = statutHttp;
  return {
    success: false,
    error: {
      code: (input.error && input.error.code) || 'OLLAMA_ERROR',
      message: (input.error && input.error.message) || ('Ollama Cloud a repondu ' + statut),
      http_status: statut
    },
    metadata: prevData.metadata,
    _trace: {
      llm_response: null,
      service_response: enveloppe,
      provider: 'ollama-cloud',
      model: prevData.model,
      tokens: { input: 0, output: 0 },
      latency_ms: latencyMs
    }
  };
}

const text = input.choices?.[0]?.message?.content || '';
// Un 200 sans texte n est pas un succes : c est un echec silencieux.
if (!text) {
  return {
    success: false,
    error: { code: 'EMPTY_RESPONSE', message: 'Ollama Cloud a repondu 200 sans texte', http_status: 502 },
    metadata: prevData.metadata,
    _trace: { llm_response: null, service_response: enveloppe, provider: 'ollama-cloud',
              model: prevData.model, tokens: { input: 0, output: 0 }, latency_ms: latencyMs }
  };
}
const finishReason = input.choices?.[0]?.finish_reason || 'stop';
const modelUsed = input.model || prevData.model;

return {
  success: true,
  data: {
    text: text,
    model: modelUsed,
    finish_reason: finishReason
  },
  meta: {
    provider: 'ollama-cloud',
    model: modelUsed,
    usage: {
      prompt_tokens: input.usage?.prompt_tokens || 0,
      completion_tokens: input.usage?.completion_tokens || 0,
      total_tokens: input.usage?.total_tokens || 0,
      // OpenAI place le cache dans `prompt_tokens_details.cached_tokens`, et les
      // jetons de raisonnement sont DÉJÀ compris dans completion_tokens — le
      // détail est fourni en supplément, jamais en remplacement (azy.daily#287).
      cache_read_input_tokens: input.usage?.prompt_tokens_details?.cached_tokens || 0,
      cache_creation_input_tokens: 0,
      reasoning_tokens: input.usage?.completion_tokens_details?.reasoning_tokens || 0
    }
  },
  metadata: prevData.metadata,
  _trace: {
    llm_response: text,
    service_response: enveloppe,
    provider: 'ollama-cloud',
    model: modelUsed,
    tokens: {
      input: input.usage?.prompt_tokens || 0,
      output: input.usage?.completion_tokens || 0
    },
    latency_ms: latencyMs
  }
};

