={{ (() => {
  const data = $json;
  // /v1/responses : `input` au lieu de `messages`, le system passe par
  // `instructions`, et les blocs changent de nom — text -> input_text
  // (output_text pour l assistant), image_url -> input_image.
  const bloc = (b, role) => {
    const texte = role === 'assistant' ? 'output_text' : 'input_text';
    if (typeof b === 'string') return { type: texte, text: b };
    if (b.type === 'text') return { type: texte, text: b.text || '' };
    if (b.type === 'image_url' && b.image_url) return { type: 'input_image', image_url: b.image_url.url || b.image_url };
    return b;
  };
  const input = (data.messages || []).map((m) => ({
    role: m.role,
    content: Array.isArray(m.content) ? m.content.map((b) => bloc(b, m.role)) : m.content
  }));
  const corps = { model: data.model, input: input };
  if (data.system) corps.instructions = data.system;
  // Meme regle que la voie chat/completions : un modele de raisonnement partage
  // son budget avec des jetons invisibles, d ou un plancher, et refuse la
  // temperature.
  if (data.raisonnement) {
    corps.max_output_tokens = Math.max(data.max_tokens, 1024);
  } else {
    corps.max_output_tokens = data.max_tokens;
    corps.temperature = data.temperature;
  }
  // Pas de tool_choice force : le modele juge s il doit chercher, et
  // search_performed dit la verite sur ce qu il a fait.
  if (data.web_search) corps.tools = [{ type: 'web_search' }];
  return JSON.stringify(corps);
})() }}

