// ============================================
// FORMAT OPENAI RESPONSES (/v1/responses)
// ============================================
// Passent ici les modeles `surface: responses` (gpt-5-pro, codex… : 404 « only
// supported in v1/responses » sur chat/completions) et TOUTE demande de
// recherche web OpenAI (azy.daily#281, #361).
// La forme n a rien de chat/completions : output[] (reasoning, web_search_call,
// message) au lieu de choices[], input_tokens/output_tokens au lieu de
// prompt/completion. Mesure du 2026-09-10.
// ⚠️ Le noeud HTTP porte fullResponse + neverError : il emet
// { statusCode, body, headers }, JAMAIS l objet d erreur au premier niveau.
// Sans cette normalisation, un 401 ressortirait en succes (cf. Format Ollama).
const enveloppe = $input.first().json;
const input = enveloppe.body !== undefined ? enveloppe.body : enveloppe;
let statutHttp = enveloppe.statusCode;
if (statutHttp === undefined) {
  const msg = String((enveloppe.error && enveloppe.error.message) || enveloppe.message || '');
  const m = msg.match(/(\d{3})\s*-\s*/);
  statutHttp = m ? parseInt(m[1], 10) : ((enveloppe.error || enveloppe.code) ? 502 : 200);
}

const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;
const trace = (texte, t) => ({ llm_response: texte, service_response: enveloppe, provider: 'openai',
  model: prevData.model, tokens: t || { input: 0, output: 0 }, latency_ms: latencyMs });

// ⚠️ Une reponse reussie porte `error: null` : on teste la valeur, pas la cle.
if (statutHttp >= 400 || input.error) {
  return {
    success: false,
    error: {
      code: (input.error && (input.error.code || input.error.type)) || 'OPENAI_ERROR',
      message: (input.error && input.error.message) || ('OpenAI a repondu ' + statutHttp),
      http_status: statutHttp >= 400 ? statutHttp : 502
    },
    metadata: prevData.metadata,
    _trace: trace(null)
  };
}

// Sources : { title, url, domain }, dedoublonnees par URL — la forme de
// l outil web-search, pour que les clients n aient qu un parseur (azy.daily#361).
const domaineDe = (url) => { const m = String(url || '').match(/^https?:\/\/([^\/]+)/); return m ? m[1] : ''; };
const sources = [];
const vues = new Set();
const ajouter = (titre, url, domaine) => {
  if (!url || vues.has(url)) return;
  vues.add(url);
  sources.push({ title: titre || 'Source', url: url, domain: domaine || domaineDe(url) });
};

const sorties = Array.isArray(input.output) ? input.output : [];
let text = '';
for (const o of sorties) {
  if (o.type !== 'message') continue;
  for (const c of (o.content || [])) {
    if (c.type !== 'output_text') continue;
    text += c.text || '';
    for (const a of (c.annotations || [])) if (a.type === 'url_citation') ajouter(a.title, a.url);
  }
}
const recherches = sorties.filter(o => o.type === 'web_search_call').length;

const incomplet = input.incomplete_details && input.incomplete_details.reason;
const finishReason = input.status === 'completed' ? 'stop'
  : (incomplet === 'max_output_tokens' ? 'length' : (incomplet || input.status || 'stop'));

// Un 200 sans texte n est pas un succes : typiquement un budget de sortie
// entierement consomme par le raisonnement (status incomplete).
if (!text) {
  return {
    success: false,
    error: { code: 'EMPTY_RESPONSE', http_status: 502,
      message: 'OpenAI a repondu sans texte (statut ' + (input.status || '?') + (incomplet ? ', ' + incomplet : '') + ')' },
    metadata: prevData.metadata,
    _trace: trace(null)
  };
}

const usage = input.usage || {};
const modelUsed = input.model || prevData.model;
const res = {
  success: true,
  data: { text: text, model: modelUsed, finish_reason: finishReason },
  meta: {
    provider: 'openai',
    model: modelUsed,
    usage: {
      prompt_tokens: usage.input_tokens || 0,
      completion_tokens: usage.output_tokens || 0,
      total_tokens: usage.total_tokens || 0,
      cache_read_input_tokens: (usage.input_tokens_details && usage.input_tokens_details.cached_tokens) || 0,
      // `input_tokens_details.cache_write_tokens` existe (mesure : 4401) mais son
      // tarif n est pas etabli : on garde 0 comme la voie chat/completions,
      // plutot que de le faire compter a 1,25× comme chez Anthropic.
      cache_creation_input_tokens: 0,
      // Deja compris dans output_tokens : detail en supplement (azy.daily#287).
      reasoning_tokens: (usage.output_tokens_details && usage.output_tokens_details.reasoning_tokens) || 0
    }
  },
  metadata: prevData.metadata,
  _trace: trace(text, { input: usage.input_tokens || 0, output: usage.output_tokens || 0 })
};
if (prevData.web_search) {
  res.data.sources = sources;
  res.meta.search_performed = recherches > 0 || sources.length > 0;
  res.meta.sources_count = sources.length;
  res.meta.usage.web_search_requests = recherches;
}
return res;

