={{ (() => {
  const data = $json;
  // /v1/conversations : outil en ligne, store:false — aucune ressource laissee
  // sur le compte (l API Agents, elle, cree un agent persistant).
  const messages = data.messages || [];
  const consignes = messages.filter((m) => m.role === 'system').map((m) => m.content);
  if (data.system) consignes.unshift(data.system);
  const corps = {
    model: data.model,
    inputs: messages.filter((m) => m.role !== 'system'),
    tools: [{ type: 'web_search' }],
    completion_args: { max_tokens: data.max_tokens, temperature: data.temperature },
    store: false
  };
  if (consignes.length) corps.instructions = consignes.join('\n\n');
  return JSON.stringify(corps);
})() }}

