// ============================================
// FORMAT MISTRAL CONVERSATIONS (/v1/conversations)
// ============================================
// Seule voie Mistral qui accepte l outil web_search (chat/completions : 400
// « WebSearchTool connector is not supported »). Forme mesuree le 2026-09-10 :
// outputs[] = tool.execution puis message.output, dont le content est une liste
// de morceaux `text` et `tool_reference`.
// ⚠️ Le noeud HTTP porte fullResponse + neverError : il emet
// { statusCode, body, headers }, JAMAIS l objet d erreur au premier niveau.
// Sans cette normalisation, un 401 ressortirait en succes (cf. Format Ollama).
const enveloppe = $input.first().json;
const input = enveloppe.body !== undefined ? enveloppe.body : enveloppe;
let statutHttp = enveloppe.statusCode;
if (statutHttp === undefined) {
  const msg = String((enveloppe.error && enveloppe.error.message) || enveloppe.message || '');
  const m = msg.match(/(\d{3})\s*-\s*/);
  statutHttp = m ? parseInt(m[1], 10) : ((enveloppe.error || enveloppe.code) ? 502 : 200);
}

const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latencyMs = Date.now() - startTime;
const trace = (texte, t) => ({ llm_response: texte, service_response: enveloppe, provider: 'mistral',
  model: prevData.model, tokens: t || { input: 0, output: 0 }, latency_ms: latencyMs });

if (statutHttp >= 400 || input.error || input.object === 'Error') {
  const brut = input.message || (input.error && input.error.message) || input.detail;
  return {
    success: false,
    error: {
      code: 'MISTRAL_ERROR',
      message: (typeof brut === 'string' ? brut : JSON.stringify(brut || '')) || ('Mistral a repondu ' + statutHttp),
      http_status: statutHttp >= 400 ? statutHttp : 502
    },
    metadata: prevData.metadata,
    _trace: trace(null)
  };
}

// Sources : { title, url, domain }, dedoublonnees par URL — la forme de
// l outil web-search, pour que les clients n aient qu un parseur (azy.daily#361).
const domaineDe = (url) => { const m = String(url || '').match(/^https?:\/\/([^\/]+)/); return m ? m[1] : ''; };
const sources = [];
const vues = new Set();
const ajouter = (titre, url, domaine) => {
  if (!url || vues.has(url)) return;
  vues.add(url);
  sources.push({ title: titre || 'Source', url: url, domain: domaine || domaineDe(url) });
};

const sorties = Array.isArray(input.outputs) ? input.outputs : [];
let text = '';
let modelUsed = prevData.model;
for (const o of sorties) {
  if (o.type !== 'message.output') continue;
  if (o.model) modelUsed = o.model;
  const c = o.content;
  if (typeof c === 'string') { text += c; continue; }
  for (const x of (c || [])) {
    if (x.type === 'text') text += x.text || '';
    else if (x.type === 'tool_reference') ajouter(x.title, x.url);
  }
}
const recherches = sorties.filter(o => o.type === 'tool.execution' && /^web_search/.test(o.name || '')).length;

if (!text) {
  return {
    success: false,
    error: { code: 'EMPTY_RESPONSE', message: 'Mistral a repondu sans texte', http_status: 502 },
    metadata: prevData.metadata,
    _trace: trace(null)
  };
}

const usage = input.usage || {};
const res = {
  success: true,
  // Conversations ne rend pas de raison d arret.
  data: { text: text, model: modelUsed, finish_reason: 'stop' },
  meta: {
    provider: 'mistral',
    model: modelUsed,
    usage: {
      // ⚠️ Mistral compte A PART les jetons que la recherche injecte
      // (connector_tokens) : 788 + 60 contre un total de 7748, dont 6900 de
      // connecteur. OpenAI et Anthropic les comptent DANS l entree (mesure :
      // 7786 et 8523 jetons d entree pour une question d une ligne). On les
      // replie dans prompt_tokens, sur le modele de la convention Gemini
      // (azy.daily#295 §2.5) : prompt + completion = total chez les quatre, et
      // un client qui affiche entree -> sortie montre ce qui a ete consomme
      // (azy.daily#361). Le detail reste fourni en supplement, jamais a la place.
      prompt_tokens: (usage.prompt_tokens || 0) + (usage.connector_tokens || 0),
      completion_tokens: usage.completion_tokens || 0,
      total_tokens: usage.total_tokens || 0,
      cache_read_input_tokens: 0,
      cache_creation_input_tokens: 0,
      reasoning_tokens: 0,
      connector_tokens: usage.connector_tokens || 0
    }
  },
  metadata: prevData.metadata,
  _trace: trace(text, { input: usage.prompt_tokens || 0, output: usage.completion_tokens || 0 })
};
if (prevData.web_search) {
  res.data.sources = sources;
  res.meta.search_performed = recherches > 0 || sources.length > 0;
  res.meta.sources_count = sources.length;
  res.meta.usage.web_search_requests = recherches;
}
return res;
